/// <reference lib="dom" />
/// <reference lib="dom.iterable" />
/// <reference lib="es2023" />

import { loadFont as loadSans } from "@remotion/google-fonts/Jost";
import {
  AbsoluteFill,
  Interactive,
  type InteractivitySchema,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  type ReactNode,
  useContext,
} from "react";
import {
  clampChroma,
  converter,
  formatRgb,
  interpolate,
  parse,
  type Rgb,
} from "culori";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

const toRgb = converter("rgb");

/**
 * Whether to warn. Read through `globalThis`, never a bare `process`: a Vite
 * project defines no `process`, so the bare name threw a ReferenceError on the
 * very input it meant to warn about — and a stock Remotion project has no Node
 * types, so the bare name was also a type error in every install.
 */
function isDev(): boolean {
  const env = (globalThis as { process?: { env?: { NODE_ENV?: string } } })
    .process?.env;
  return env?.NODE_ENV !== "production";
}

function resolveColorString(s: string): string {
  const trimmed = s.trim();
  if (trimmed.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `mixOklch cannot resolve CSS variable "${trimmed}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return "#000";
  }
  if (!parse(trimmed)) {
    if (isDev()) {
      console.warn(`mixOklch could not parse "${trimmed}"; using black.`);
    }
    return "#000";
  }
  return trimmed;
}

function mixOklch(a: string, b: string, t: number): string {
  const mixed = clampChroma(
    interpolate([resolveColorString(a), resolveColorString(b)], "oklch")(t),
    "oklch",
    "rgb",
  );
  return toCss(toRgb(mixed));
}

function toCss(color: Rgb): string {
  return formatRgb(color);
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#1d6bff", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#1d6bff",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#1d6bff", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#1d6bff",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

/**
 * A column of words that spins like a reel and stops on one of them.
 *
 * A fixed lead-in — "Acme for" — holds the left of the line, and the word
 * that finishes the sentence lives in a slot to its right. The slot is one row
 * of a taller column: the words above and below it are visible, smaller and
 * grey, fading out toward the top and bottom of the frame. The column rolls,
 * decelerates over about a second and three quarters, and comes to rest with
 * one word at full size and in ink.
 *
 * ## Everything here was measured off a recording, frame by frame
 *
 * The numbers below are not taste. They were recovered from a 2.1 second,
 * 638 × 354 screen capture by thresholding the ink in each of its 80 frames:
 *
 *   - the row pitch is exactly **34px**, and every row's baseline — including
 *     the oversized selected one — sits on that grid to the pixel. That is the
 *     tell that the scale pivots on the baseline, which is also the only pivot
 *     that does not make scaled type climb the pixel grid (see below).
 *   - the selected word is **1.665×** the others. Measured on the same word in
 *     both states, twice: "Growth" 97.15/58.28 = 1.6671, "Educators"
 *     128.55/77.35 = 1.6618.
 *   - the reel travels **9 rows**, and the whole curve is in `ROLL` — it is not
 *     a bezier and not a spring. The best cubic-bezier fit is 1.8px RMS and
 *     5.5px off at worst, the best spring 4.3px RMS. A fifth of a row is a
 *     visibly different frame, so the measurement ships instead of a curve.
 *
 * ## The selection lags the slot, and that is the whole feel of it
 *
 * A row becomes the selected one when it is nearest the slot — when its
 * baseline is within half a pitch. But it does not *arrive* at full size the
 * instant it crosses: the reference shows the same row at |d| = 17px reading
 * 0.30 on the way in and 0.685 on the way out. That hysteresis is a transition
 * lagging a class change, and it is why the fast part of the roll never looks
 * like a row of identical pops — each word is still growing when the next one
 * takes over. `SWAP` is that lag.
 *
 * ## The face is Jost, and that was measured too
 *
 * The reference is set in a licensed brand face, so the question was which
 * available one has its *proportions*. Fingerprinted on two space-free words at
 * matched cap height — "Framer" and "Growth", in cap units — the reference reads
 * 4.025 and 4.353. Jost reads 4.153 and 4.265; Outfit 4.491 and 4.529; Poppins
 * 5.201 and 5.180. Jost is within 3%, everything else is 10% or worse, and a
 * word 10% wide is a word that no longer ends where the sentence needs it to.
 *
 * ## Two fixed left edges
 *
 * The selected word's ink starts 30.5px left of everyone else's, so it butts up
 * against the lead-in and completes the sentence while the column itself stays
 * indented and out of the way. Both edges are constant across every word and
 * every frame — the reel is left-aligned twice over, not centred once.
 */

const { fontFamily: SANS } = loadSans("normal", {
  weights: ["400", "500", "600"],
  subsets: ["latin"],
});

/* ─────────────────────────────────────────────────────────────────────────
   The scene, in the reference's own 638 × 354 pixels
   ───────────────────────────────────────────────────────────────────────── */

const REF_W = 638;
const REF_H = 354;

/** Row-to-row distance. Measured on eight consecutive baselines: 34.0 each. */
const PITCH = 34;
/** The slot's baseline — where the sentence sits. */
const BASE_Y = 183.8;
/** Left of the line's box. The reference's lead-in ink starts at 203.55. */
const LINE_X = 201.98;
/**
 * The space between the end of the lead-in and the selected word.
 *
 * Measured as a gap rather than as the word's x, and that distinction is the
 * whole reason this scene survives having its copy changed: the reference's word
 * sits at 345.29 only because "Framer for" happens to end at 336.56. Pin the
 * word to 345 and a shorter lead-in leaves a hole, a longer one runs the two
 * together — which is exactly what "Acme forLaunches" did before this was a
 * gap.
 */
const GAP = 8.01;
/**
 * How far right the column sits from the word that completes the sentence.
 *
 * The reel is indented and the selected word is not: it steps left out of the
 * column to finish the line, and steps back when it loses the slot. Both edges
 * are constant across every word and every frame of the reference — the reel is
 * left-aligned twice over, not centred once.
 */
const INDENT = 30.87;

/** Type size of the selected word. Cap height measured at 22.32px. */
const SIZE = 30.63;
/** Box top → baseline, at `lineHeight: 1`. A face metric, measured, not guessed. */
const ASC = 25.43;
/** Unselected scale. The reciprocal of the measured 1.665. */
const SMALL = 1 / 1.665;

/**
 * How long a row takes to grow into the slot, in seconds, and its curve.
 *
 * Measured from the frame a row crosses half a pitch: 0.90 at 38ms, and inside
 * the noise floor of a width measurement thereafter. A settle worth one frame
 * is a settle; this one is worth two.
 */
const SWAP = 0.07;

/**
 * The reel's own deceleration, as (seconds, share of the travel).
 *
 * Recovered from the recording by taking the phase of the 34px row grid in each
 * frame's vertical ink profile — which reads the offset to a hundredth of a
 * pixel off all eleven visible rows at once, rather than tracking one word and
 * inheriting its glyphs. Frames the capture sampled twice are dropped: they are
 * the recorder's duplicates, not the page's, and keeping them would freeze the
 * render for a frame in exactly the places the reference is moving fastest.
 */
const ROLL: readonly (readonly [number, number])[] = [
  [0.1583, 0.00033],
  [0.175, 0.02175],
  [0.2083, 0.05298],
  [0.2417, 0.08995],
  [0.275, 0.13203],
  [0.3083, 0.18194],
  [0.3417, 0.23034],
  [0.3833, 0.28119],
  [0.4167, 0.32889],
  [0.45, 0.37627],
  [0.4833, 0.42203],
  [0.5167, 0.46322],
  [0.5583, 0.50415],
  [0.575, 0.54044],
  [0.6083, 0.57445],
  [0.6417, 0.6073],
  [0.675, 0.63751],
  [0.7083, 0.66516],
  [0.7417, 0.69074],
  [0.775, 0.71485],
  [0.8083, 0.73897],
  [0.8417, 0.75963],
  [0.875, 0.77896],
  [0.9083, 0.79751],
  [0.9417, 0.81422],
  [0.975, 0.83177],
  [1.0167, 0.84767],
  [1.05, 0.86162],
  [1.0833, 0.87394],
  [1.1167, 0.88608],
  [1.1417, 0.89735],
  [1.175, 0.9077],
  [1.2083, 0.91734],
  [1.2417, 0.92633],
  [1.275, 0.93528],
  [1.3083, 0.94438],
  [1.35, 0.95087],
  [1.3833, 0.95819],
  [1.4417, 0.96961],
  [1.475, 0.97442],
  [1.5083, 0.97863],
  [1.5417, 0.98239],
  [1.575, 0.98571],
  [1.6083, 0.98903],
  [1.6417, 0.99161],
  [1.6833, 0.99381],
  [1.7167, 0.99569],
  [1.75, 0.99732],
  [1.7833, 0.99858],
  [1.8083, 0.99926],
  [1.8417, 1],
];

/**
 * How far a row is faded, by its distance from the slot as a share of the frame.
 *
 * Read as an envelope: the brightest any pixel of an unselected row ever got at
 * each height, across all 80 frames. Taking the maximum over the whole reel is
 * what makes it a property of the *position* rather than of whichever word
 * happened to be sitting there — a word with no ascenders is dimmer at the same
 * height, and one sample would have read that as a dip in the fade.
 *
 * It does not reach zero: the column is cut off by the frame, not by the fade.
 */
const FADE: readonly (readonly [number, number])[] = [
  [0, 1],
  [0.085, 0.97],
  [0.155, 0.89],
  [0.22, 0.744],
  [0.288, 0.518],
  [0.356, 0.357],
  [0.424, 0.25],
  [0.492, 0.185],
];

type Table = readonly (readonly [number, number])[];

/**
 * Linear read of a rising table, in either direction.
 *
 * `at = 0` reads y from x — the reel's travel at a second. `at = 1` reads x from
 * y — the second the reel reaches a share of its travel, which is what tells a
 * row when it takes the slot. Both tables here are sorted and monotone in both
 * columns, so one walk serves both and there is no second function to keep in
 * step with the first.
 */
function read(table: Table, v: number, at: 0 | 1 = 0): number {
  const to = at === 0 ? 1 : 0;
  const first = table[0];
  const last = table[table.length - 1];
  if (!first || !last) return 0;
  if (v <= first[at]) return first[to];
  if (v >= last[at]) return last[to];
  for (let i = 1; i < table.length; i++) {
    const hi = table[i];
    const lo = table[i - 1];
    if (hi && lo && v <= hi[at]) {
      return lo[to] + ((hi[to] - lo[to]) * (v - lo[at])) / (hi[at] - lo[at]);
    }
  }
  return last[to];
}

/**
 * The second the reel has travelled `p` of its distance.
 *
 * Outside the roll it answers with an infinity rather than an endpoint: a row
 * the reel never reaches must never take the slot, and a row it started past
 * must have held it from the first frame. Clamping instead would hand both of
 * those a real time and make the scene swap words it never touches.
 */
function rollReaches(p: number): number {
  const first = ROLL[0];
  const last = ROLL[ROLL.length - 1];
  if (!first || !last) return Number.POSITIVE_INFINITY;
  if (p <= first[1]) return Number.NEGATIVE_INFINITY;
  if (p > last[1]) return Number.POSITIVE_INFINITY;
  return read(ROLL, p, 1);
}

/** The swap's curve: a moderate decelerate, clamped. */
function swell(t: number): number {
  if (t <= 0) return 0;
  if (t >= SWAP) return 1;
  const u = t / SWAP;
  return 1 - (1 - u) ** 3;
}

export interface WordWheelProps {
  /** The part of the line that never changes. */
  headline?: string;
  /** The reel, in order. It cycles, so the column is never empty. */
  words?: string;
  /** Rows travelled. Left at the list's length the reel comes full circle. */
  spin?: number;
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  fontFamily?: string;
}

function WordWheelScene({
  headline = "Made for",
  words = "Launches, Founders, Indie hackers, Agencies, Designers, Startups, Dev tools, Solo builders, Changelogs",
  spin,
  theme,
  mode = "light",
  fontFamily = "Default",
}: WordWheelProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const t = useKitTheme(theme, mode);
  const face = resolveFont(fontFamily) ?? SANS;

  const reel = words
    .split(",")
    .map((w) => w.trim())
    .filter(Boolean);
  const rows = reel.length || 1;
  const travel = (spin ?? rows) * PITCH;

  /**
   * One unit of reference pixel, and the offset that centres the layout.
   *
   * The scene is laid out in the recording's own pixels and scaled by height, so
   * a render at the reference's dimensions is the reference's dimensions and
   * nothing is resampled in the middle of a comparison.
   */
  const u = height / REF_H;
  const ox = (width - REF_W * u) / 2;

  const now = frame / fps;
  const s = read(ROLL, now) * travel;

  const first = Math.ceil((s - BASE_Y - PITCH) / PITCH);
  const last = Math.floor((s - BASE_Y + REF_H + PITCH) / PITCH);

  const ink = t.foreground;
  const dim = t.mutedForeground;

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={{ backgroundColor: t.background }}
    >
      <div
        style={{
          position: "absolute",
          left: ox,
          top: 0,
          width: REF_W * u,
          height: REF_H * u,
          fontFamily: face,
          fontWeight: 500,
          // Hinting re-snaps every stem as the scale slides, and the letterforms
          // boil. This turns it off — the type reads a shade softer, which is the
          // outline as it actually is.
          textRendering: "geometricPrecision",
          whiteSpace: "nowrap",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: LINE_X * u,
            top: (BASE_Y - ASC) * u,
            fontSize: SIZE * u,
            lineHeight: 1,
            color: ink,
          }}
        >
          {headline}
          {/*
            A zero-sized inline-block sits on the baseline at the end of the
            lead-in's own advance, whatever that lead-in says. The reel hangs off
            it, so the sentence stays a sentence when the copy changes — and the
            anchor never needs measuring, because the browser has already done
            the layout by the time it paints.
          */}
          <span
            style={{ position: "relative", display: "inline-block", width: 0 }}
          >
            {Array.from({ length: last - first + 1 }, (_, n) => {
              const i = first + n;
              const y = BASE_Y + PITCH * i - s;
              const d = y - BASE_Y;

              // A row owns the slot while it is nearest to it, and grows into it
              // over SWAP rather than on the frame it crosses.
              const p =
                swell(now - rollReaches((PITCH * (i - 0.5)) / travel)) -
                swell(now - rollReaches((PITCH * (i + 0.5)) / travel));

              const scale = SMALL + (1 - SMALL) * p;
              return (
                <div
                  key={i}
                  style={{
                    position: "absolute",
                    left: (GAP + INDENT) * u,
                    top: (y - ASC - BASE_Y) * u,
                    color: p > 0 ? mixOklch(dim, ink, p) : dim,
                    opacity: read(FADE, Math.abs(d) / REF_H),
                    // The baseline is the only pivot a browser will not round:
                    // it quantises a glyph's origin to a whole device pixel
                    // vertically, so a scale that moves the baseline makes the
                    // word climb the grid in jumps. Pivot on it and there is
                    // nothing to snap.
                    transform: `translateX(${-INDENT * p * u}px) scale(${scale})`,
                    transformOrigin: `0px ${ASC * u}px`,
                  }}
                >
                  {reel[((i % rows) + rows) % rows]}
                </div>
              );
            })}
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio
   ───────────────────────────────────────────────────────────────────────── */

type WordWheelElementProps = Omit<
  ComponentProps<typeof WordWheelScene>,
  | "from"
  | "durationInFrames"
  | "trimBefore"
  | "playbackRate"
  | "loop"
  | "freeze"
  | "hidden"
  | "name"
  | "showInTimeline"
  | "cropLeft"
  | "cropRight"
  | "cropTop"
  | "cropBottom"
  | "premountFor"
  | "postmountFor"
  | "styleWhilePremounted"
  | "styleWhilePostmounted"
  | "controls"
> & {
  readonly style?: CSSProperties;
};

/** What a prop falls back to when Studio does not pass it, reset included. */
const WordWheelDefaults = {
  headline: "Made for",
  words:
    "Launches, Founders, Indie hackers, Agencies, Designers, Startups, Dev tools, Solo builders, Changelogs",
  spin: 9,
  mode: "light",
  theme: { background: "transparent" },
} satisfies Partial<WordWheelElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const WordWheelSchema = {
  headline: {
    type: "text-content",
    default: "Made for",
    description: "Lead-in",
  },
  words: {
    type: "text-content",
    default:
      "Launches, Founders, Indie hackers, Agencies, Designers, Startups, Dev tools, Solo builders, Changelogs",
    description: "Reel (comma separated)",
  },
  spin: {
    type: "number",
    default: 9,
    min: 1,
    max: 40,
    step: 1,
    description: "Rows travelled",
    hiddenFromList: false,
    keyframable: false,
  },
  mode: {
    type: "enum",
    default: "light",
    description: "Theme",
    variants: { light: {}, dark: {} },
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function WordWheelFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const WordWheelInner = forwardRef<HTMLDivElement, WordWheelElementProps>(
  ({ style, ...props }, ref) => {
    // The layer's length, from the Sequence `wrapInSequence` puts around this.
    const { durationInFrames } = useVideoConfig();
    const rest = { ...WordWheelDefaults, ...props };
    // The scene measures its copy once, on mount. An Inspector edit changes the
    // props without remounting it, so the key does.
    const key = JSON.stringify(props, (k, v) =>
      k === "children" ? undefined : v,
    );

    // width/height are what useVideoConfig() reports inside this Sequence, so
    // the scene lays itself out in its stage rather than the whole composition.
    // It is not a layer of its own: the one Studio shows is the wrapper's.
    return (
      <Sequence
        layout="none"
        showInTimeline={false}
        durationInFrames={durationInFrames}
        width={700}
        height={532}
      >
        <div
          ref={ref}
          style={{
            position: "relative",
            width: 700,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
            ...style,
          }}
        >
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 94,
              width: 700,
              height: 532,
            }}
          >
            <WordWheelFade>
              <WordWheelScene key={key} {...rest} />
            </WordWheelFade>
          </div>
        </div>
      </Sequence>
    );
  },
);

export const WordWheel = Interactive.withSchema({
  Component: WordWheelInner,
  componentName: "<WordWheel>",
  schema: WordWheelSchema,
  wrapInSequence: true,
});
